    { q: "What is the name of Nigeria's national anthem adopted in 2024?", options: ["A) Arise, O Compatriots", "B) God Save the King", "C) Nigeria We Hail Thee", "D) Land of Hope"], answer: 2, explanation: "Nigeria We Hail Thee was adopted as Nigeria's national anthem in 2024.", topic: "National Anthem" },
    { q: "What does the green colour on the Nigerian flag represent?", options: ["A) Agriculture and natural wealth", "B) War", "C) Darkness", "D) The sea only"], answer: 0, explanation: "The green bands represent Nigeria's agricultural wealth and natural resources.", topic: "National Symbols" },
    { q: "What does the white colour on the Nigerian flag represent?", options: ["A) Danger", "B) Peace", "C) Rain", "D) Night"], answer: 1, explanation: "The white band represents peace and unity.", topic: "National Symbols" },
    { q: "What is democracy?", options: ["A) Rule by one family forever", "B) Rule by soldiers only", "C) A system in which people choose their leaders", "D) A school game"], answer: 2, explanation: "Democracy allows citizens to choose their leaders through elections.", topic: "Democracy" },
    { q: "What is an election?", options: ["A) A process of choosing leaders by voting", "B) A type of meal", "C) A school uniform", "D) A road sign"], answer: 0, explanation: "An election is a process through which people vote to choose leaders or representatives.", topic: "Elections" },
    { q: "Who is a leader?", options: ["A) Someone who always causes trouble", "B) Someone who guides or directs a group", "C) Someone who steals from a group", "D) Someone who refuses every duty"], answer: 1, explanation: "A leader guides people and helps a group work towards its goals.", topic: "Leadership" },
    { q: "Which quality should a good leader have?", options: ["A) Dishonesty", "B) Cruelty", "C) Fairness", "D) Selfishness"], answer: 2, explanation: "A good leader should treat people fairly.", topic: "Leadership" },
    { q: "Who is the leader of a school?", options: ["A) Head teacher or principal", "B) School visitor", "C) Bus passenger", "D) Market trader"], answer: 0, explanation: "The head teacher or principal is responsible for leading the school.", topic: "Leadership" },
    { q: "Why should we obey traffic rules?", options: ["A) To cause accidents", "B) To keep road users safe", "C) To delay everyone", "D) To block roads"], answer: 1, explanation: "Traffic rules help prevent accidents and protect road users.", topic: "Obedience to Rules" },
    { q: "What should you do when the traffic light is red?", options: ["A) Run across", "B) Drive faster", "C) Stop", "D) Ignore it"], answer: 2, explanation: "A red traffic light means road users must stop.", topic: "Road Safety" },
    { q: "What is public property?", options: ["A) Property provided for community use", "B) A person's private toothbrush", "C) A child's personal shoe", "D) A family photograph"], answer: 0, explanation: "Public property is provided for use by members of the public.", topic: "Public Property" },
    { q: "Which of these is public property?", options: ["A) A private diary", "B) A public school building", "C) A personal phone", "D) A family bed"], answer: 1, explanation: "A public school building is a facility provided for public education.", topic: "Public Property" },
    { q: "What should you do to public property?", options: ["A) Break it", "B) Write on it", "C) Protect and care for it", "D) Steal it"], answer: 2, explanation: "Public property belongs to the community and should be protected.", topic: "Public Property" },
    { q: "Why should people pay lawful taxes?", options: ["A) To help provide public services", "B) To destroy roads", "C) To stop schools from working", "D) To encourage stealing"], answer: 0, explanation: "Taxes help governments provide services such as roads, schools and hospitals.", topic: "Civic Duties" },
    { q: "Which of these is a public service?", options: ["A) Private birthday party", "B) Public healthcare", "C) Personal shopping", "D) Family dinner"], answer: 1, explanation: "Public healthcare is a service provided for the benefit of the community.", topic: "Public Services" },
    { q: "What should you do if you see someone damaging a public facility?", options: ["A) Join the person", "B) Cheer the person", "C) Report it to a responsible adult or authority", "D) Hide the damage"], answer: 2, explanation: "Reporting damage helps responsible people protect public property.", topic: "Civic Responsibility" },
    { q: "What does unity mean?", options: ["A) Staying together and working as one", "B) Fighting all the time", "C) Refusing to cooperate", "D) Separating everyone"], answer: 0, explanation: "Unity means people coming together and working towards shared goals.", topic: "Unity" },
    { q: "Why should Nigerians respect people from other ethnic groups?", options: ["A) To create arguments", "B) To promote unity and peaceful living", "C) To encourage discrimination", "D) To stop friendships"], answer: 1, explanation: "Respecting different ethnic groups promotes national unity and peace.", topic: "National Unity" },
    { q: "Which of these is a way to show patriotism?", options: ["A) Destroying national symbols", "B) Disrespecting the country", "C) Respecting national symbols and helping the country", "D) Breaking public laws"], answer: 2, explanation: "Patriotism means showing love and commitment to one's country.", topic: "Patriotism" },
    { q: "What is a community rule?", options: ["A) An agreed instruction that guides behaviour", "B) A type of food", "C) A musical instrument", "D) A market stall"], answer: 0, explanation: "Community rules guide how people behave and live together.", topic: "Community Rules" },
    { q: "Which behaviour should be avoided in public places?", options: ["A) Keeping the area clean", "B) Fighting and damaging property", "C) Respecting others", "D) Waiting patiently"], answer: 1, explanation: "Fighting and damaging property can hurt people and harm the community.", topic: "Good Behaviour" },
    { q: "What should you do when someone is speaking politely to you?", options: ["A) Shout at the person", "B) Walk away angrily", "C) Listen and respond politely", "D) Insult the person"], answer: 2, explanation: "Listening and responding politely show good manners.", topic: "Good Manners" },
    { q: "What is bullying?", options: ["A) Repeatedly hurting or intimidating another person", "B) Helping a classmate", "C) Sharing books", "D) Playing fairly"], answer: 0, explanation: "Bullying involves repeated behaviour intended to hurt, frighten or control another person.", topic: "Child Protection" },
    { q: "What should you do if you witness bullying at school?", options: ["A) Join in", "B) Tell a teacher or trusted adult", "C) Encourage the bully", "D) Record and share it for fun"], answer: 1, explanation: "Reporting bullying to a responsible adult helps protect the pupil being harmed.", topic: "Child Protection" },
    { q: "Which action shows good citizenship in the neighbourhood?", options: ["A) Throwing rubbish into drains", "B) Stealing from neighbours", "C) Helping to keep the surroundings clean", "D) Breaking streetlights"], answer: 2, explanation: "Keeping the neighbourhood clean is a useful community responsibility.", topic: "Community Service" },
    { q: "Why should we listen to other people's opinions?", options: ["A) To understand different ideas", "B) To make everyone afraid", "C) To stop people from learning", "D) To encourage quarrels"], answer: 0, explanation: "Listening helps us understand others and solve disagreements peacefully.", topic: "Tolerance" }
