    { q: "What is national unity?", options: ["A) People fighting one another", "B) People refusing to cooperate", "C) People living and working together as one country", "D) People destroying public property"], answer: 2, explanation: "National unity means people from different groups work together as one nation.", topic: "National unity" },
    { q: "Which action promotes unity in Nigeria?", options: ["A) Discrimination", "B) Insulting other groups", "C) Spreading hatred", "D) Respecting people from different ethnic groups"], answer: 3, explanation: "Respecting people from different ethnic groups helps strengthen national unity.", topic: "National unity" },
    { q: "What is democracy?", options: ["A) A system of government in which people have a say in choosing their leaders", "B) A system where nobody follows rules", "C) A type of school game", "D) A method of farming"], answer: 0, explanation: "Democracy allows citizens to participate in choosing their leaders, usually through elections.", topic: "Democracy" },
    { q: "What is an election?", options: ["A) A school cleaning exercise", "B) A process of choosing leaders by voting", "C) A football competition", "D) A family meeting"], answer: 1, explanation: "An election is a process through which people vote to choose leaders or representatives.", topic: "Elections" },
    { q: "What should a voter do during an election?", options: ["A) Sell their ballot paper", "B) Vote more than once", "C) Vote freely and peacefully", "D) Destroy voting materials"], answer: 2, explanation: "Voters should make their choices freely and follow election rules.", topic: "Responsible voting" },
    { q: "What is a national anthem?", options: ["A) A market song", "B) A birthday song", "C) A school bell", "D) A song that expresses a country's identity and values"], answer: 3, explanation: "A national anthem is an official song that expresses a country's identity and ideals.", topic: "National symbols" },
    { q: "How should pupils behave when the national anthem is being sung?", options: ["A) Stand respectfully and remain orderly", "B) Shout and run around", "C) Fight with one another", "D) Play games"], answer: 0, explanation: "Standing respectfully during the national anthem shows respect for the country.", topic: "Respect for national symbols" },
    { q: "What is patriotism?", options: ["A) Hating everyone", "B) Love and loyalty towards one's country", "C) Refusing to obey laws", "D) Damaging public property"], answer: 1, explanation: "Patriotism means showing love, loyalty and concern for one's country.", topic: "Patriotism" },
    { q: "Which action shows patriotism?", options: ["A) Destroying public property", "B) Cheating fellow citizens", "C) Helping to keep the country clean", "D) Disobeying every law"], answer: 2, explanation: "Keeping the environment clean is one way citizens can contribute to their country.", topic: "Patriotism" },
    { q: "Why should citizens obey the law?", options: ["A) To encourage crime", "B) To create confusion", "C) To promote fighting", "D) To maintain peace, safety and order"], answer: 3, explanation: "Laws help protect people and maintain order in society.", topic: "Obedience to law" },
    { q: "What should you do if you see someone being bullied?", options: ["A) Report it to a trusted adult or teacher", "B) Join the bullying", "C) Laugh at the victim", "D) Encourage the bully"], answer: 0, explanation: "Reporting bullying to a trusted adult helps protect the person being bullied.", topic: "Bullying prevention" }
