    { q: "Èwo ni ọ̀rọ̀ ìṣe?", options: ["A) Sáré", "B) Àga", "C) Ilé", "D) Ìwé"], answer: 0, explanation: "Sáré jẹ́ ọ̀rọ̀ ìṣe nítorí pé ó ń ṣàpèjúwe ìṣe.", topic: "Ọ̀rọ̀ Ìṣe" },
    { q: "Kí ni a fi ń fọ eyín?", options: ["A) Ọṣẹ́ aṣọ", "B) Bọ́ọ̀lù", "C) Fọ́ọ̀ṣì eyín", "D) Abẹ́"], answer: 2, explanation: "A fi fọ́ọ̀ṣì eyín fọ eyín.", topic: "Ìmọ́tótó Ara" },
    { q: "Èwo ni ọ̀rọ̀ tó tọ́ fún ẹranko tó ń fún wa ní wàrà?", options: ["A) Màlúù", "B) Ẹyẹ", "C) Eku", "D) Ẹja"], answer: 0, explanation: "Màlúù lè fún wa ní wàrà.", topic: "Ẹranko Ilé" },
    { q: "Kí ni a ń pè ní ẹni tó ń gbin irúgbìn?", options: ["A) Dókítà", "B) Àgbẹ̀", "C) Olùkọ́", "D) Adájọ́"], answer: 1, explanation: "Àgbẹ̀ ni ẹni tó ń gbin irúgbìn tí ó sì ń tọ́jú oko.", topic: "Iṣẹ́ Àwọn Ènìyàn" },
    { q: "Ọ̀rọ̀ wo ni ó jẹ́ orúkọ ohun èlò ìrìnàjò?", options: ["A) Ọkọ̀", "B) Ìwé", "C) Àga", "D) Omi"], answer: 0, explanation: "Ọkọ̀ jẹ́ ohun èlò tí a fi ń rìnrìn-àjò.", topic: "Ìrìnàjò" },
    { q: "Kí ni ìtumọ̀ 'ilé ìwòsàn' ní èdè Gẹ̀ẹ́sì?", options: ["A) School", "B) Hospital", "C) Market", "D) Church"], answer: 1, explanation: "Ilé ìwòsàn túmọ̀ sí hospital.", topic: "Àwọn Ibi" },
    { q: "Èwo ni ọ̀rọ̀ tó tọ́ fún àwọ̀ ewé ní èdè Gẹ̀ẹ́sì?", options: ["A) Yellow", "B) Green", "C) White", "D) Black"], answer: 1, explanation: "Àwọ̀ ewé túmọ̀ sí green.", topic: "Àwọ̀" },
    { q: "Kí ni a ń pè ní ọmọ ajá?", options: ["A) Ọmọ ológbò", "B) Ọmọ ajá", "C) Ọmọ ewúrẹ́", "D) Ọmọ màlúù"], answer: 1, explanation: "Ọmọ ajá ni ọmọ tí ajá bí.", topic: "Ẹranko" },
    { q: "Èwo ni ọ̀rọ̀ tó fi hàn pé ohun kan ju ẹyọ kan lọ?", options: ["A) Ọ̀kan", "B) Ọ̀pọ̀", "C) Kéré", "D) Tútù"], answer: 1, explanation: "Ọ̀pọ̀ ń fi hàn pé ohun kan pọ̀ ju ẹyọ kan lọ.", topic: "Ìṣirò Ọ̀rọ̀" },
    { q: "Kí ni a ń pè ní ẹni tó ń wakọ̀ ọkọ̀?", options: ["A) Awakọ̀", "B) Àgbẹ̀", "C) Olùkọ́", "D) Dókítà"], answer: 0, explanation: "Awakọ̀ ni ẹni tó ń wakọ̀ ọkọ̀.", topic: "Iṣẹ́ Àwọn Ènìyàn" },
    { q: "Èwo ni ọ̀rọ̀ àtakò sí 'gíga'?", options: ["A) Kúkúrú", "B) Gùn", "C) Títóbi", "D) Fẹ́lẹ́"], answer: 0, explanation: "Kúkúrú ni àtakò sí gíga nígbà tí a bá ń ṣàpèjúwe gígùn tàbí ìga.", topic: "Ọ̀rọ̀ Àtakò" },
    { q: "Kí ni a ń pè ní ibi tí a ti ń ra àti tà ọjà?", options: ["A) Ilé ìwé", "B) Ọjà", "C) Ilé ìwòsàn", "D) Ilé ìjọsìn"], answer: 1, explanation: "Ọjà ni ibi tí ènìyàn ti ń ra àti tà ọjà.", topic: "Àwọn Ibi" },
    { q: "Ọ̀rọ̀ wo ni ó jẹ́ orúkọ oúnjẹ?", options: ["A) Ìrẹsì", "B) Àga", "C) Pẹ́ńsù", "D) Bọ́ọ̀lù"], answer: 0, explanation: "Ìrẹsì jẹ́ orúkọ oúnjẹ.", topic: "Oúnjẹ" },
    { q: "Kí ni a fi ń gbọ́ ohùn?", options: ["A) Ojú", "B) Imú", "C) Etí", "D) Ẹnu"], answer: 2, explanation: "Etí ni ẹ̀yà ara tí a fi ń gbọ́ ohùn.", topic: "Ẹ̀yà Ara" },
    { q: "Kí ni a fi ń ríran?", options: ["A) Ojú", "B) Etí", "C) Ẹsẹ̀", "D) Ọwọ́"], answer: 0, explanation: "Ojú ni ẹ̀yà ara tí a fi ń ríran.", topic: "Ẹ̀yà Ara" },
    { q: "Èwo ni ọ̀rọ̀ tó tọ́ fún 'thank you' ní Yorùbá?", options: ["A) Ẹ kú àárọ̀", "B) Ẹ ṣé", "C) Ó dàbọ̀", "D) Ẹ káàbọ̀"], answer: 1, explanation: "Ẹ ṣé ni ọ̀nà ìdúpẹ́ ní èdè Yorùbá.", topic: "Ìkíni àti Ìdúpẹ́" },
    { q: "Kí ni a máa ń sọ nígbà tí a bá pàdé ẹnìkan ní òwúrọ̀?", options: ["A) Ẹ kú alẹ́", "B) Ẹ kú àárọ̀", "C) Ó dàbọ̀", "D) Ẹ má bínú"], answer: 1, explanation: "Ẹ kú àárọ̀ ni ìkíni tí a ń lò ní òwúrọ̀.", topic: "Ìkíni" },
    { q: "Èwo ni ọ̀rọ̀ ìkíni nígbà tí a bá ń lọ kúrò lọ́dọ̀ ẹnìkan?", options: ["A) Ẹ káàbọ̀", "B) Ẹ kú iṣẹ́", "C) Ó dàbọ̀", "D) Ẹ kú àárọ̀"], answer: 2, explanation: "Ó dàbọ̀ ni a ń sọ nígbà tí a bá ń lọ.", topic: "Ìkíni" },
    { q: "Kí ni ìtumọ̀ 'ilé ẹ̀kọ́' ní èdè Gẹ̀ẹ́sì?", options: ["A) School", "B) Hospital", "C) Farm", "D) Shop"], answer: 0, explanation: "Ilé ẹ̀kọ́ túmọ̀ sí school.", topic: "Ìtumọ̀ Ọ̀rọ̀" },
    { q: "Èwo ni ọ̀kan lára àwọn ohun èlò tí a fi ń gé aṣọ?", options: ["A) Abẹ́rẹ́", "B) Àpótí", "C) Àpẹ̀rẹ̀", "D) Àkàrà"], answer: 0, explanation: "Abẹ́rẹ́ ni a fi ń rán aṣọ, ṣùgbọ́n scissors ni a fi ń gé aṣọ. Nínú àwọn àṣàyàn wọ̀nyí, kò sí ohun èlò tó péye fún gígé aṣọ.", topic: "Ohun Èlò Ilé" },
    { q: "Kí ni a ń pè ní ọmọ ewúrẹ́?", options: ["A) Ọmọ màlúù", "B) Ọmọ ewúrẹ́", "C) Ọmọ ẹṣin", "D) Ọmọ adìẹ"], answer: 1, explanation: "Ọmọ ewúrẹ́ ni ọmọ tí ewúrẹ́ bí.", topic: "Ẹranko" },
    { q: "Èwo ni ọ̀rọ̀ tó tọ́ fún 'fire' ní Yorùbá?", options: ["A) Omi", "B) Iná", "C) Afẹ́fẹ́", "D) Ilẹ̀"], answer: 1, explanation: "Iná túmọ̀ sí fire.", topic: "Ìtumọ̀ Ọ̀rọ̀" },
    { q: "Kí ni a ń pè ní ohun tí a fi ń kọ́ lẹ́tà sí ẹlòmíràn?", options: ["A) Lẹ́tà", "B) Àga", "C) Ìkòkò", "D) Bọ́ọ̀lù"], answer: 0, explanation: "Lẹ́tà ni ìwé tí a kọ láti fi ránṣẹ́ sí ẹlòmíràn.", topic: "Ìbánisọ̀rọ̀" },
    { q: "Ọ̀rọ̀ wo ni ó jẹ́ orúkọ ibi tí a ti ń sin Ọlọ́run?", options: ["A) Ọjà", "B) Ilé ìjọsìn", "C) Ilé ìwé", "D) Oko"], answer: 1, explanation: "Ilé ìjọsìn ni ibi tí àwọn ènìyàn ti ń ṣe ìjọsìn.", topic: "Àwọn Ibi" },
    { q: "Kí ni ọ̀rọ̀ àtakò sí 'rírẹ̀'?", options: ["A) Alágbára", "B) Aláìlera", "C) Àìsàn", "D) Tútù"], answer: 0, explanation: "Alágbára ń fi agbára hàn, ó sì jẹ́ àtakò tó yẹ sí rírẹ̀ ní àyíká ìtumọ̀ yìí.", topic: "Ọ̀rọ̀ Àtakò" },
    { q: "Èwo ni àwọ̀ ọ̀run ní ọjọ́ tí kò ní ìkùukùu sábà máa ń jẹ́?", options: ["A) Dúdú", "B) Búlúù", "C) Pupa", "D) Funfun"], answer: 1, explanation: "Ọ̀run sábà máa ń dà bí àwọ̀ búlúù ní ọjọ́ tí kò ní ìkùukùu.", topic: "Àwọ̀" },
    { q: "Kí ni a ń pè ní ìwé tí a fi ń ka ìtàn?", options: ["A) Ìwé ìtàn", "B) Àga", "C) Àwo", "D) Ọkọ̀"], answer: 0, explanation: "Ìwé ìtàn ni ìwé tí a fi ń ka àwọn ìtàn.", topic: "Àwọn Ohun Èlò" },
    { q: "Èwo ni ọ̀rọ̀ tó fi ìwà rere hàn?", options: ["A) Jíjà", "B) Irọ́ pípa", "C) Ìgbọràn", "D) Olè jíjà"], answer: 2, explanation: "Ìgbọràn jẹ́ ìwà rere tó ń fi hàn pé ènìyàn ń tẹ̀lé ìtọ́ni tó yẹ.", topic: "Ìwà Rere" },
    { q: "Kí ni a yẹ kí a ṣe kí a tó jẹ oúnjẹ?", options: ["A) Fọ ọwọ́", "B) Ṣeré pẹ̀lú ilẹ̀", "C) Mu omi ẹrẹ̀", "D) Fi ọwọ́ ẹlẹ́gbin kan oúnjẹ"], answer: 0, explanation: "Fífọ ọwọ́ kí a tó jẹun ń ran wa lọ́wọ́ láti yẹra fún kòkòrò àrùn.", topic: "Ìmọ́tótó" },
    { q: "Èwo ni ọ̀rọ̀ tó tọ́ fún 'friend' ní Yorùbá?", options: ["A) Ọ̀tá", "B) Ọ̀rẹ́", "C) Àlejò", "D) Ọ̀gá"], answer: 1, explanation: "Ọ̀rẹ́ túmọ̀ sí friend.", topic: "Ìtumọ̀ Ọ̀rọ̀" }
