  "SSS 1|Accounting": [{ "q": "The accounting equation is", "options": ["A) Assets = Capital + Liabilities", "B) Assets = Capital - Liabilities", "C) Capital = Assets + Liabilities", "D) Assets = Sales + Purchases"], "answer": 0, "explanation": "The basic accounting equation is Assets = Capital + Liabilities.", "topic": "" },
  { "q": "A cash book records", "options": ["A) cash and bank transactions", "B) only credit sales", "C) only purchases", "D) only depreciation"], "answer": 0, "explanation": "The cash book records cash and bank receipts and payments.", "topic": "" },
  { "q": "A debit entry generally increases", "options": ["A) assets and expenses", "B) liabilities only", "C) capital only", "D) income only"], "answer": 0, "explanation": "Under the normal rules, asset and expense accounts increase on the debit side.", "topic": "" },
  { "q": "A credit entry generally increases", "options": ["A) liabilities, capital and income", "B) assets only", "C) expenses only", "D) drawings only"], "answer": 0, "explanation": "Liability, capital and income accounts normally increase by credits.", "topic": "" },
  { "q": "The document issued to a buyer after a sale on credit is a", "options": ["A) invoice", "B) receipt", "C) cheque", "D) voucher"], "answer": 0, "explanation": "An invoice records details of goods sold and amount due.", "topic": "" },
  { "q": "A receipt is evidence of", "options": ["A) money received", "B) goods ordered only", "C) goods returned only", "D) stock counted only"], "answer": 0, "explanation": "A receipt acknowledges payment received.", "topic": "" },
  { "q": "Depreciation is", "options": ["A) decrease in value of a non-current asset over time/use", "B) increase in cash", "C) increase in capital always", "D) a sales discount"], "answer": 0, "explanation": "Depreciation allocates the depreciable amount of an asset over its useful life.", "topic": "" },
  { "q": "Gross profit is", "options": ["A) Sales - Cost of goods sold", "B) Sales + expenses", "C) Capital - drawings", "D) Assets - liabilities"], "answer": 0, "explanation": "Gross profit equals net sales less cost of goods sold.", "topic": "" },
  { "q": "Working capital is", "options": ["A) Current assets - Current liabilities", "B) Fixed assets - capital", "C) Sales - purchases", "D) Capital + drawings"], "answer": 0, "explanation": "Working capital measures the short-term net resources available for operations.", "topic": "" },
  { "q": "A trial balance is prepared mainly to", "options": ["A) test the arithmetical equality of ledger balances", "B) calculate rainfall", "C) replace final accounts", "D) record only cash"], "answer": 0, "explanation": "Equal debit and credit totals provide a basic arithmetical check.", "topic": "" },
  { "q": "Drawings are", "options": ["A) amounts or goods withdrawn by the owner for personal use", "B) business income", "C) business liabilities", "D) sales returns"], "answer": 0, "explanation": "Drawings reduce the owner's equity in the business.", "topic": "" },
  { "q": "Bad debt is", "options": ["A) an amount owed by a customer that is considered irrecoverable", "B) cash discount", "C) capital introduced", "D) stock purchased"], "answer": 0, "explanation": "A bad debt is an irrecoverable receivable.", "topic": "" },
  { "q": "A balance sheet is now commonly called the", "options": ["A) statement of financial position", "B) cash book", "C) journal", "D) sales ledger"], "answer": 0, "explanation": "The statement of financial position reports assets, liabilities and equity at a date.", "topic": "" },
  { "q": "A journal is used to", "options": ["A) record transactions before posting to ledgers in appropriate cases", "B) store cash physically", "C) measure stock weight", "D) issue passports"], "answer": 0, "explanation": "Journals are books of original/prime entry for specified transactions.", "topic": "" },
  { "q": "A current asset is", "options": ["A) cash", "B) building", "C) machinery", "D) long-term investment"], "answer": 0, "explanation": "Cash is a current asset because it is readily available for operations.", "topic": "" },
  { "q": "A current liability is", "options": ["A) trade payable", "B) building", "C) motor vehicle", "D) capital"], "answer": 0, "explanation": "Trade payables are obligations expected to be settled in the short term.", "topic": "" },
  { "q": "A bank reconciliation statement explains differences between", "options": ["A) cash book bank balance and bank statement balance", "B) sales and purchases only", "C) capital and drawings", "D) stock and wages"], "answer": 0, "explanation": "It reconciles the business cash book with the bank's records.", "topic": "" },
  { "q": "Carriage inward is normally included in", "options": ["A) cost of purchases", "B) sales revenue", "C) capital", "D) drawings"], "answer": 0, "explanation": "Carriage inward is a cost of bringing purchased goods into the business.", "topic": "" },
  { "q": "Carriage outward is normally treated as", "options": ["A) selling/distribution expense", "B) purchase cost", "C) capital introduced", "D) liability"], "answer": 0, "explanation": "Carriage outward is incurred to deliver goods to customers.", "topic": "" },
  { "q": "A contra entry in a cash book occurs when", "options": ["A) cash is transferred between cash and bank columns", "B) goods are returned", "C) sales are made on credit", "D) a fixed asset is depreciated"], "answer": 0, "explanation": "A contra entry records transfers between cash and bank within the cash book.", "topic": "" },
  { "q": "The principle that expenses should be recognized in the period they help generate revenue is related to", "options": ["A) matching", "B) dual citizenship", "C) monopoly", "D) specialization"], "answer": 0, "explanation": "The matching principle aligns relevant expenses with the revenue period.", "topic": "" },
  { "q": "Capital expenditure is expenditure on", "options": ["A) acquiring or improving non-current assets", "B) daily stationery only", "C) wages only", "D) electricity only"], "answer": 0, "explanation": "Capital expenditure provides enduring benefits through non-current assets.", "topic": "" },
  { "q": "Revenue expenditure is generally", "options": ["A) expenditure incurred for day-to-day operations", "B) purchase of a building", "C) issue of shares", "D) purchase of long-term land"], "answer": 0, "explanation": "Revenue expenditure relates to current operations and benefits are generally consumed in the period.", "topic": "" },
  { "q": "A suspense account may be used temporarily when", "options": ["A) an accounting difference has not yet been located", "B) all accounts are perfect", "C) no transaction exists", "D) stock is unavailable"], "answer": 0, "explanation": "A suspense account temporarily holds an unexplained difference pending correction.", "topic": "" },
  { "q": "The double-entry principle means", "options": ["A) every transaction has equal debit and credit effects", "B) every transaction is recorded twice on the same side", "C) only cash transactions are recorded", "D) every account must have two owners"], "answer": 0, "explanation": "Each transaction affects at least two accounts with equal total debits and credits.", "topic": "" }],

